from abc import ABCMeta, abstractmethod
import logging
import six
from taf.internal.managedobject import ManagedObject
from .exceptions import ExecutionError

logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


@six.add_metaclass(ABCMeta)
class Executor(ManagedObject):
    """
    Run commands.
    """

    def __init__(self, sudo_password=None, **kwargs):
        super(Executor, self).__init__(**kwargs)
        self._sudo_password = sudo_password

    @property
    def sudo_password(self):
        return self._sudo_password

    def execute(self, command, use_tty=False):
        """
        Execute a command and wait until it finishes.

        :param str command: command to be executed
        :param bool use_tty: if True, use a terminal when executing the command

        :return: stdout
        :rtype: bytes
        :raise: ExecutionError, if stderr is not empty or exit status is not 0
        """
        stdout, stderr, exit_status = self.raw_execute(command, use_tty=use_tty)
        if exit_status:
            raise ExecutionError(
                stdout=stdout,
                stderr=stderr,
                exit_status=exit_status)
        else:
            return stdout

    @abstractmethod
    def raw_execute(self, command, use_tty=False):
        """
        Execute a command and wait until it finishes.

        Adds logging and optionally retry to execution of command.

        :param str command: command to be executed
        :param bool use_tty: if True, use a terminal when executing the command

        :return: stdout, stderr, exit status
        :rtype: bytes, bytes, int
        """

    def _raw_execute(self, command, use_tty=False):
        """
        Execute a command and wait until it finishes.

        :param str command: command to be executed
        :param bool use_tty: if True, use a terminal when executing the command

        :return: stdout, stderr, exit status
        :rtype: bytes, bytes, int
        """
        process = self._start(
            command=command,
            use_tty=use_tty)
        stdout, stderr = process._read_output()
        process.wait()
        exit_status = process.exit_status
        return stdout, stderr, exit_status

    @abstractmethod
    def start(self, command, use_tty=False):
        """
        Start a command.

        Adds logging and optionally retry to start of command.

        :param str command: command to be executed
        :param bool use_tty: if True, use a terminal when executing the command

        :return: process
        :rtype: Process
        """

    @abstractmethod
    def _start(self, command, use_tty=False):
        """
        Start a command.

        :param str command: command to be executed
        :param bool use_tty: if True, use a terminal when executing the command

        :return: process
        :rtype: Process
        """

    def sudo_prefix(self):
        user_id = int(self.execute(b"id -u"))
        if user_id == 0 or user_id == 9999:
            sudo_prefix = ""
        elif self._sudo_password is None:
            sudo_prefix = "sudo "
        else:
            sudo_prefix = "echo '{sudo_password}' | sudo -S ".format(
                sudo_password=self._sudo_password)
        return sudo_prefix
